import CoreText
import OSLog
import SwiftUI

private let fontLogger = Logger(subsystem: "com.ironflow.app", category: "fonts")

/// Inter, the font of every text of the app (DESIGN.md), in the five weights it uses: the files Google
/// Fonts serves (Inter 4, the text design), whole, with their license in `Resources/Fonts/OFL.txt`.
/// They are registered for the app's process when it starts: the Info.plist is generated by Xcode,
/// so it does not list them.
enum InterFont {
    /// The PostScript names of the files, which are also their names in the bundle.
    static let regular = "Inter-Regular"
    static let medium = "Inter-Medium"
    static let semibold = "Inter-SemiBold"
    static let bold = "Inter-Bold"
    static let extraBold = "Inter-ExtraBold"

    static let allNames = [regular, medium, semibold, bold, extraBold]

    /// The file of a weight. The app uses regular, medium, semibold, bold and heavy; a lighter weight
    /// reads as Regular, and black as ExtraBold, the heaviest file.
    static func name(for weight: Font.Weight) -> String {
        switch weight {
        case .medium: medium
        case .semibold: semibold
        case .bold: bold
        case .heavy, .black: extraBold
        default: regular
        }
    }

    /// Registers the files for this process; once is enough, and a second time changes nothing. A file
    /// that cannot be registered is logged, and its texts use the system font: the app goes on. Returns
    /// the names of those files.
    @discardableResult
    static func register(in bundle: Bundle = .main) -> [String] {
        var failed: [String] = []
        for name in allNames {
            guard let url = bundle.url(forResource: name, withExtension: "ttf") else {
                failed.append(name)
                continue
            }
            var error: Unmanaged<CFError>?
            if CTFontManagerRegisterFontsForURL(url as CFURL, .process, &error) {
                continue
            }
            let code = error.map { CFErrorGetCode($0.takeRetainedValue()) }
            if code != CTFontManagerError.alreadyRegistered.rawValue {
                failed.append(name)
            }
        }
        if !failed.isEmpty {
            fontLogger.error("Fonts not registered: \(failed.joined(separator: ", "), privacy: .public)")
        }
        return failed
    }
}
